const cfg = $input.first().json;
if (!cfg.imageUrl) throw new Error('Set Config.imageUrl 이 비어 있습니다.');
if (cfg.driveActuallyRun && !cfg.runDriveCheck) throw new Error('driveActuallyRun=true 이면 runDriveCheck=true 필요');
const out = {
  ...cfg,
  actuallyRun: !!cfg.driveActuallyRun,
  query: cfg.productName,
  mode: cfg.driveMode || cfg.mode || 'image-cuts',
};
return [{ json: out }];

const cfg = $('Assert Config').first().json;
const child = $input.first().json;
if (child && child.ready === false) throw new Error('01 Health 실패: ' + (child.message || ''));
return [{ json: { ...cfg, health: child, stage: '01' } }];

const prev = $('After 01').first().json;
const child = $input.first().json || {};
const project_id = child.project_id || child.projectId || '';
if (!project_id) throw new Error('02 분석 결과 project_id 없음');
return [{ json: { ...prev, ...child, project_id, stage: '02' } }];

const prev = $input.first().json;
if (!prev.project_id) throw new Error('runAnalyze=false 이면 project_id 를 Set Config에 넣으세요');
return [{ json: { ...prev, skipped_02: true } }];

const prev = $('After 02').first().json;
const child = $input.first().json || {};
const project_id = child.project_id || child.projectId || prev.project_id || '';
return [{ json: { ...prev, ...child, project_id, ['result_07']: child, stage: '07' } }];

const prev = $('After 07').first().json;
const child = $input.first().json || {};
const project_id = child.project_id || child.projectId || prev.project_id || '';
return [{ json: { ...prev, ...child, project_id, ['result_03']: child, stage: '03' } }];

const prev = $('After 03').first().json;
const child = $input.first().json || {};
const project_id = child.project_id || child.projectId || prev.project_id || '';
return [{ json: { ...prev, ...child, project_id, ['result_04']: child, stage: '04' } }];

const prev = $('After 04').first().json;
const child = $input.first().json || {};
const project_id = child.project_id || child.projectId || prev.project_id || '';
return [{ json: { ...prev, ...child, project_id, ['result_05']: child, stage: '05' } }];

const prev = $('After 05').first().json;
const child = $input.first().json || {};
const project_id = child.project_id || child.projectId || prev.project_id || '';
return [{ json: { ...prev, ...child, project_id, ['result_08']: child, stage: '08' } }];

const prev = $('After 08').first().json;
const child = $input.first().json || {};
const project_id = child.project_id || child.projectId || prev.project_id || '';
return [{ json: { ...prev, ...child, project_id, ['result_09']: child, stage: '09' } }];

const cfg = $('Assert Config').first().json;
const last = $input.first().json;
const projectId = last.project_id || '';
const base = String(cfg.backendBase || '').replace(/\/+$/, '');
return [{
  json: {
    ok: true,
    stage: 'master-complete',
    orchestration: 'execute-workflow-chain',
    project_id: projectId,
    productName: cfg.productName,
    imageUrl: cfg.imageUrl,
    healthReady: last.health?.ready ?? null,
    flags: {
      runAnalyze: !!cfg.runAnalyze,
      runDbCandidates: !!cfg.runDbCandidates,
      runCompetitors: !!cfg.runCompetitors,
      runGenerateAll: !!cfg.runGenerateAll,
      runExport: !!cfg.runExport,
      runDriveCheck: !!cfg.runDriveCheck,
      driveActuallyRun: !!cfg.driveActuallyRun,
      runCafe24DryRun: !!cfg.runCafe24DryRun,
    },
    urls: projectId ? {
      project: base + '/api/projects/' + projectId,
      full: base + '/api/projects/' + projectId + '/full',
      export: base + '/api/projects/' + projectId + '/export',
    } : null,
    note: '00 Master → Execute Workflow(01~09). 하위는 단독 실행 가능.',
    finishedAt: new Date().toISOString(),
  }
}];

const cfg = $('Config Ready').first().json;
function pick(name) { try { return $(name).first().json; } catch (e) { return { _error: String(e.message || e) }; } }
const backend = pick('Backend Health');
const provider = pick('Provider Health');
const pdp = pick('PDP Automation Health');
const hub = pick('API Hub Health');
const backendOk = Array.isArray(backend) && backend.length > 0 && !backend._error;
const providerOk = !!(provider && provider.gemini_route && !provider._error && !provider.error);
const pdpOk = !!(pdp && (pdp.ok === true || pdp.status) && !pdp._error);
const hubOk = hub?.ok === true;
const ready = backendOk && hubOk;
return [{
  json: {
    ...cfg,
    backendOk,
    providerOk,
    pdpAutomationOk: pdpOk,
    apiHubOk: hubOk,
    ready,
    gemini_route: provider?.gemini_route || null,
    google_cloud_project: provider?.google_cloud_project || null,
    sectionCount: Array.isArray(backend) ? backend.length : 0,
    message: ready
      ? `조립공장 n8n 게이트 통과 (sections=${Array.isArray(backend) ? backend.length : 0}, route=${provider?.gemini_route || '?'}, hub=ok)`
      : `게이트 실패 backendOk=${backendOk} apiHubOk=${hubOk} providerOk=${providerOk} pdpOk=${pdpOk}`,
    checkedAt: new Date().toISOString()
  }
}];

const cfg = $('Config Ready').first().json;
// Binary must come from Download Image URL or a prior Read Binary File node named 'Product Image File'
let item;
try {
  item = $('Download Image URL').first();
} catch (e) {
  try { item = $('Product Image File').first(); } catch (e2) {
    throw new Error('이미지가 없습니다. Set Config.imageUrl 을 채우거나, Read Binary File 노드(이름: Product Image File)를 연결하세요.');
  }
}
if (!item.binary || !Object.keys(item.binary).length) {
  throw new Error('바이너리 이미지가 비어 있습니다. imageUrl 또는 로컬 파일을 확인하세요.');
}
const binKey = Object.keys(item.binary)[0];
return [{
  json: {
    backendBase: cfg.backendBase,
    productName: cfg.productName,
    llmModel: cfg.llmModel,
    oauthReady: !!$('Check GPT OAuth Session').first().json?.oauthStatus?.chatGptLoginReady
      || !!$('Check GPT OAuth Session').first().json?.chatGptLoginReady
  },
  binary: { data: item.binary[binKey] }
}];

const created = $('Create Project').first().json;
const analyzed = $('Analyze Product').first().json;
const cfg = $('Config Ready').first().json;
return [{
  json: {
    stage: '02-input-analyze',
    project_id: created.project_id,
    productName: cfg.productName,
    analyzeStatus: analyzed.status || (analyzed.error ? 'error' : 'unknown'),
    analysis: analyzed.analysis || null,
    error: analyzed.error || created.error || null,
    backendBase: cfg.backendBase,
    apiHubBase: cfg.apiHubBase,
    llmModel: cfg.llmModel,
    nextStep: '03-competitors 또는 04-generate-all-sections'
  }
}];

const cfg = $('Config Ready').first().json;
const res = $input.first().json;
return [{
  json: {
    stage: '03-competitors',
    project_id: cfg.project_id,
    backendBase: cfg.backendBase,
    status: res.status || (res.error ? 'error' : 'ok'),
    competitor_data: res.competitor_data || res || null,
    error: res.error || null,
    nextStep: '04-generate-all-sections'
  }
}];

const cfg = $input.first().json;
if (!cfg.project_id) throw new Error('Set Config.project_id 가 비어 있습니다. 02-input-analyze 결과 project_id 를 넣으세요.');
return [{ json: cfg }];

const cfg = $('Config Ready').first().json;
const start = $('Generate All Sections').first().json;
const backend = String(cfg.backendBase || 'http://127.0.0.1:5050').replace(/\/+$/, '');
const projectId = cfg.project_id;
const pollSeconds = Math.max(5, Number(cfg.generatePollSeconds || 15));
const maxPolls = Math.max(1, Number(cfg.generatePollMax || 120));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let last = null;
let polls = 0;
let done = false;
for (let i = 0; i < maxPolls; i++) {
  await sleep(pollSeconds * 1000);
  polls = i + 1;
  last = await this.helpers.httpRequest({
    method: 'GET',
    url: `${backend}/api/projects/${projectId}`,
    json: true,
    timeout: 30000,
  });
  const st = String(last?.status || '');
  if (st === 'completed' || st === 'error') {
    done = true;
    break;
  }
}

if (!done) {
  throw new Error(`generate-all 타임아웃: ${polls}회 폴링 후에도 status=${last?.status || 'unknown'} (progress=${last?.progress ?? '?'})`);
}
if (last?.status === 'error') {
  throw new Error(`generate-all 실패: ${last?.progress_message || 'error'}`);
}

return [{
  json: {
    stage: '04-generate-all-sections',
    project_id: projectId,
    backendBase: backend,
    generateStart: start,
    status: last.status,
    progress: last.progress,
    progress_message: last.progress_message,
    sections_completed: last.sections_completed,
    polls,
    pollSeconds,
    nextStep: '05-export',
    error: null
  }
}];

const cfg = $('Config Ready').first().json;
const exp = $('Export JSON').first().json;
let html = null;
try { html = $('Export HTML').first().json; } catch(e) { html = null; }
const base = cfg.backendBase.replace(/\/+$/,'');
return [{
  json: {
    stage: '05-export',
    project_id: cfg.project_id,
    exportJson: exp,
    exportHtmlPreview: typeof html === 'string' ? html.slice(0, 500) : html,
    urls: {
      full: `${base}/api/projects/${cfg.project_id}/full`,
      export: `${base}/api/projects/${cfg.project_id}/export`,
      exportHtml: `${base}/api/projects/${cfg.project_id}/export-html`,
      ui: 'http://127.0.0.1:8081/app.html'
    },
    note: 'Cafe24 등록은 브라우저 조립공장에서 검수 후 진행하세요.',
    nextStep: 'manual-cafe24-or-done'
  }
}];

const cfg = $('Config Ready').first().json;
function arr(data) {
  if (Array.isArray(data)) return data;
  const body = data?.response?.body ?? data?.body ?? data;
  if (Array.isArray(body)) return body;
  if (Array.isArray(body?.products)) return body.products;
  if (Array.isArray(body?.items)) return body.items;
  if (Array.isArray(body?.results)) return body.results;
  if (Array.isArray(body?.value)) return body.value;
  return [];
}
function pick(name) {
  try { return $(name).first().json; } catch(e) { return null; }
}
const hubSinhwa = pick('Sinhwa Search via API Hub');
const directSinhwa = pick('Sinhwa Search Direct 8200');
const cafe24 = pick('Cafe24 Products Search');
const sinhwaLocal = pick('Sinhwa Local Status');
const sinhwaProducts = arr(hubSinhwa).length ? arr(hubSinhwa) : arr(directSinhwa);
const cafe24Products = arr(cafe24);
const sinhwaSource = arr(hubSinhwa).length ? 'api-hub' : (arr(directSinhwa).length ? 'direct-8200' : 'none');
return [{
  json: {
    stage: '07-db-candidates',
    query: cfg.query,
    sinhwaLocalStatus: sinhwaLocal,
    sinhwaSource,
    sinhwaCount: sinhwaProducts.length,
    cafe24Count: cafe24Products.length,
    sinhwaTop: sinhwaProducts.slice(0, 5).map(p => ({
      name: p.product_name || p.jname || p.name || '',
      code: p.jcode || p.product_code || p.code || '',
      score: p.score || p.match_score || null
    })),
    cafe24Top: cafe24Products.slice(0, 5).map(p => ({
      name: p.product_name || p.name || '',
      product_no: p.product_no || p.productNo || '',
      product_code: p.product_code || p.productCode || '',
      price: p.price || p.selling_price || null
    })),
    raw: {
      sinhwaHubOk: !!(hubSinhwa && hubSinhwa.ok !== false),
      cafe24HubOk: !!(cafe24 && cafe24.ok !== false)
    },
    nextStep: '브라우저 조립공장에서 후보 확정 또는 04-generate-all',
    note: '원본 조립공장 후보 수집 API와 동일 경로. n8n은 검색/상위 후보만 반환하며 자동 확정은 하지 않습니다.'
  }
}];

