parameters.jsCode:
const bus = $('Prep G3 VM Lists').first().json;
const form = $input.first().json || {};
const raw = String(form.selectedVmIndexes || '').trim();
let idxs = [];
if (raw && raw !== '-1') {
  idxs = raw.split(/[,\s]+/).map(x => Number(x)).filter(n => Number.isFinite(n) && n >= 0);
}
const selected = idxs.map(i => bus.vmCandidates[i]).filter(Boolean);
return [{
  json: {
    ...bus,
    selectedVmIndexes: idxs,
    selectedVm: selected,
    stage: 'g3-selected'
  }
}];

const bus = $('Apply G3 VM Selection').first().json;
const full = $input.first().json || {};
const gen = (() => { try { return $('Auto: 04 Generate (hero/cuts/detail 근사)').first().json; } catch(e) { return {}; } })();
const base = String(bus.backendBase || 'http://127.0.0.1:5050').replace(/\/+$/, '');
function absUrl(u) {
  const s = String(u || '').trim();
  if (!s) return '';
  if (/^https?:\/\//i.test(s)) return s;
  if (s.startsWith('/')) return base + s;
  return base + '/' + s.replace(/^\/+/, '');
}
const assets = [];
// 0) 입력/대표 원본
if (full.product_image_url || bus.imageUrl) {
  assets.push({
    id: 'input:product',
    stage: 'input',
    label: '입력 제품 이미지',
    url: absUrl(full.product_image_url || bus.imageUrl),
    kind: 'image'
  });
}
// 1) 섹션 생성 이미지 = 앱 hero/cuts/detail 산출물의 API 근사 목록
const sections = full.sections && typeof full.sections === 'object' ? full.sections : {};
const sectionIds = Object.keys(sections).sort((a, b) => {
  const na = Number(sections[a]?.section_number || sections[a]?.order || 0);
  const nb = Number(sections[b]?.section_number || sections[b]?.order || 0);
  return na - nb;
});
for (const sid of sectionIds) {
  const s = sections[sid] || {};
  const imageUrl = s.image_url || s.imageUrl || '';
  const title = s.section_name || s.name || s.title || sid;
  if (imageUrl) {
    assets.push({
      id: 'section:' + sid,
      stage: 'section',
      sectionId: sid,
      label: title,
      url: absUrl(imageUrl),
      kind: 'image',
      hasContent: !!(s.content || s.text || s.body)
    });
  } else if (s.content || s.text || s.body) {
    assets.push({
      id: 'section-text:' + sid,
      stage: 'section',
      sectionId: sid,
      label: title + ' (텍스트만)',
      url: '',
      kind: 'text',
      hasContent: true
    });
  }
}
const pickList = assets.length
  ? assets.map((a, i) => `${i}: ${a.id} | [${a.stage}] ${a.label}${a.url ? ' | ' + a.url : ''}`).join('\n')
  : '0: (생성 이미지 없음 — 재생성 또는 stop_review_in_app)';
const allIds = assets.map(a => a.id).join(',');
const imageOnlyIds = assets.filter(a => a.kind === 'image').map(a => a.id).join(',');
const note = `generate status=${gen.status || full.status || '?'} · assets=${assets.length} · images=${assets.filter(a => a.kind === 'image').length}`;
return [{
  json: {
    ...bus,
    projectFull: { id: full.id, status: full.status, progress: full.progress },
    generateResult: gen,
    generatedAssets: assets,
    assetPickList: pickList,
    allAssetIds: allIds,
    imageOnlyAssetIds: imageOnlyIds,
    generatedNote: note,
    stage: 'g4-catalog'
  }
}];

const bus = $('Prep G4 Asset Catalog').first().json;
const form = $input.first().json || {};
const mode = String(form.selectionMode || 'ids').trim();
const assets = Array.isArray(bus.generatedAssets) ? bus.generatedAssets : [];
const byId = Object.fromEntries(assets.map(a => [a.id, a]));
const byIndex = assets;

if (mode === 'handback_app') {
  return [{
    json: {
      ...bus,
      assetPolicy: 'stop_review_in_app',
      selectedAssetNote: form.assetNote || '',
      selectedAssetIds: [],
      selectedAssets: [],
      stage: 'g4-handback-app',
      ok: true,
      message: '앱 조립공장 assets 탭 핸드오프'
    }
  }];
}

let ids = [];
if (mode === 'all_images') {
  ids = assets.filter(a => a.kind === 'image').map(a => a.id);
} else if (mode === 'all') {
  ids = assets.map(a => a.id);
} else {
  const raw = String(form.selectedAssetIds || '').trim();
  if (!raw) throw new Error('G4: selectedAssetIds 비어 있음 (또는 selectionMode=all_images)');
  if (raw.toLowerCase() === 'all') {
    ids = assets.filter(a => a.kind === 'image').map(a => a.id);
  } else {
    const parts = raw.split(/[,\n]+/).map(s => s.trim()).filter(Boolean);
    for (const p of parts) {
      if (/^\d+$/.test(p)) {
        const a = byIndex[Number(p)];
        if (a) ids.push(a.id);
      } else if (byId[p]) {
        ids.push(p);
      } else {
        // partial section id allow section:xxx
        const hit = assets.find(a => a.id === p || a.sectionId === p || a.id.endsWith(':' + p));
        if (hit) ids.push(hit.id);
      }
    }
  }
}

ids = [...new Set(ids)];
const selectedAssets = ids.map(id => byId[id]).filter(Boolean);
if (!selectedAssets.length) {
  throw new Error('G4: 유효한 선택이 없습니다. 목록 ID/번호를 확인하세요.');
}
const selectedUrls = selectedAssets.filter(a => a.url).map(a => a.url);
return [{
  json: {
    ...bus,
    assetPolicy: mode,
    selectedAssetNote: form.assetNote || '',
    selectedAssetIds: ids,
    selectedAssets,
    selectedAssetUrls: selectedUrls,
    selectedCount: selectedAssets.length,
    stage: 'g5-ready'
  }
}];

const bus = $('Apply G4 Asset Selection').first().json;
const form = $input.first().json || {};
if (String(form.approveDetail) !== 'yes') throw new Error('G5: 상세 생성 거부됨');
return [{ json: { ...bus, detailReady: true, stage: 'g5-approved' } }];

const bus = $('Apply G5 Approve').first().json;
const exp = $('Auto: 05 Export').first().json || {};
const form = $input.first().json || {};
const runDry = String(form.runCafe24DryRun) === 'yes';
const publishApproved = String(form.publishApproved) === 'true';
if (publishApproved) {
  // live 전송은 의도적으로 여기서 실행하지 않음 (브라우저/CDP)
}
return [{
  json: {
    ...bus,
    exportResult: exp,
    runCafe24DryRun: runDry,
    publishApproved,
    stage: runDry ? 'g7-dryrun' : 'g7-done',
    livePublishBlocked: true,
    livePublishNote: 'live 전송은 앱 publish/CDP 경로. n8n은 승인 기록 + dry-run만.'
  }
}];

const bus = $('Apply G7').first().json;
let dry = null;
try { dry = $('Auto: 09 Cafe24 DryRun').first().json; } catch(e) { dry = null; }
const base = String(bus.backendBase || '').replace(/\/+$/, '');
return [{
  json: {
    ok: true,
    orchestration: 'factory-hitl-line',
    stage: 'complete',
    project_id: bus.project_id,
    productName: bus.productName,
    gates: {
      g0_input: true,
      g1_db_select: !!(bus.confirmedSinhwa || bus.confirmedCafe24),
      g2_fields: (bus.missingFields || []).length === 0,
      g3_vm_select: true,
      g4_assets: !!(bus.selectedAssetIds && bus.selectedAssetIds.length) || !!bus.assetPolicy,
      g5_detail: !!bus.detailReady,
      g7_publish_decision: true,
      live_blocked: true
    },
    confirmedSinhwa: bus.confirmedSinhwa,
    confirmedCafe24: bus.confirmedCafe24,
    productFields: bus.productFields,
    selectedVmCount: (bus.selectedVm || []).length,
    selectedAssetIds: bus.selectedAssetIds || [],
    selectedAssetUrls: bus.selectedAssetUrls || [],
    selectedCount: bus.selectedCount || 0,
    dryRun: dry,
    urls: bus.project_id ? {
      project: base + '/api/projects/' + bus.project_id,
      full: base + '/api/projects/' + bus.project_id + '/full',
      export: base + '/api/projects/' + bus.project_id + '/export',
      app: 'http://127.0.0.1:8081/app.html'
    } : null,
    finishedAt: new Date().toISOString(),
    note: '조립공장과 같은 게이트 순서. 개별 썸네일 픽커 UX는 Form 한계로 ID/정책 선택. live 전송은 앱/CDP.'
  }
}];

const bus = $('Load Goal Policy').first().json;
const health = $input.first().json || {};
if (health.ready === false) throw new Error('Health fail: ' + (health.message || ''));
return [{ json: { ...bus, health, stage: 'm0-health-ok' } }];

const bus = $('After 01').first().json;
const child = $input.first().json || {};
const project_id = child.project_id || child.projectId || '';
if (!project_id) throw new Error('no project_id after analyze');
return [{ json: { ...bus, ...child, project_id, productName: bus.productName, query: bus.productName, stage: 'g0-analyzed' } }];

const bus = $('After 02 + Policy Name').first().json;
const child = $input.first().json || {};
const sinhwa = Array.isArray(child.sinhwaTop) ? child.sinhwaTop : [];
const cafe = Array.isArray(child.cafe24Top) ? child.cafe24Top : [];
const si = Number(bus.sinhwaIndex ?? 0);
const ci = Number(bus.cafe24Index ?? 0);
const confirmedSinhwa = sinhwa[si] || sinhwa[0] || null;
const confirmedCafe24 = cafe[ci] || cafe[0] || null;
return [{ json: { ...bus, dbChild: child, sinhwaCandidates: sinhwa, cafe24Candidates: cafe, confirmedSinhwa, confirmedCafe24, stage: 'g1-policy' } }];

const bus = $input.first().json;
const analysis = bus.analysis || {};
const d = bus.fieldDefaults || {};
const productFields = {
  productName: bus.productName || analysis.product_name || '',
  category: analysis.category || d.category || '',
  material: (analysis.materials && analysis.materials[0]) || analysis.material || d.material || '',
  width_mm: analysis.width_mm || analysis.size_width || d.width_mm || '',
  height_mm: analysis.height_mm || analysis.size_height || d.height_mm || '',
  weight_g: analysis.weight_g || d.weight_g || '',
  price: analysis.price_range_estimate || d.price || '',
  origin: analysis.origin || d.origin || '대한민국',
};
const required = ['productName','category','material','width_mm','height_mm'];
const missingFields = required.filter(k => !String(productFields[k]||'').trim());
if (missingFields.length) throw new Error('G2 still missing after policy: ' + missingFields.join(','));
return [{ json: { ...bus, productFields, missingFields: [], stage: 'g2-policy' } }];

const bus = $('Policy G2 Fields').first().json;
const child = $input.first().json || {};
let list = [];
if (Array.isArray(child.competitor_data?.similar_products)) list = child.competitor_data.similar_products;
else if (Array.isArray(child.similar_products)) list = child.similar_products;
else if (Array.isArray(child.competitors)) list = child.competitors;
const raw = String(bus.selectedVmIndexes || '0');
const idxs = raw.split(/[,\s]+/).map(Number).filter(n => Number.isFinite(n) && n >= 0).slice(0, Number(bus.vmTopK||2));
const selectedVm = idxs.map(i => list[i]).filter(Boolean);
return [{ json: { ...bus, vmCandidates: list, selectedVmIndexes: idxs, selectedVm, stage: 'g3-policy' } }];

const bus = $('Policy G3 VM Select').first().json;
const full = $input.first().json || {};
const gen = (() => { try { return $('Run 04 Generate All').first().json; } catch(e) { return {}; } })();
const base = String(bus.backendBase||'').replace(/\/+$/,'');
function absUrl(u){ const s=String(u||'').trim(); if(!s)return''; if(/^https?:\/\//i.test(s))return s; return base+(s.startsWith('/')?s:'/'+s); }
const assets = [];
if (full.product_image_url || bus.imageUrl) {
  assets.push({ id:'input:product', stage:'input', label:'입력 제품', url: absUrl(full.product_image_url||bus.imageUrl), kind:'image' });
}
const sections = full.sections || {};
for (const sid of Object.keys(sections)) {
  const s = sections[sid]||{};
  const imageUrl = s.image_url || s.imageUrl || '';
  const title = s.section_name || s.name || sid;
  if (imageUrl) assets.push({ id:'section:'+sid, stage:'section', sectionId:sid, label:title, url:absUrl(imageUrl), kind:'image' });
}
const mode = (bus.assetSelect && bus.assetSelect.mode) || 'all_images';
let selected = assets;
if (mode === 'all_images') selected = assets.filter(a => a.kind==='image');
const selectedAssetIds = selected.map(a => a.id);
const selectedAssetUrls = selected.map(a => a.url).filter(Boolean);
const sectionImageCount = assets.filter(a => a.id.startsWith('section:') && a.kind==='image').length;
return [{ json: {
  ...bus,
  generateResult: gen,
  projectFullStatus: full.status,
  generatedAssets: assets,
  selectedAssetIds,
  selectedAssets: selected,
  selectedAssetUrls,
  selectedCount: selected.length,
  sectionImageCount,
  sectionCount: Object.keys(sections).length,
  stage: 'g4-policy'
} }];
